/* Veille PRISME : carte de vigilance de Météo-France → table Vigilances du document Grist (et journal des changements).
   Lancé toutes les 30 minutes par le déclencheur. Une ligne par département, phénomène et échéance (aujourd'hui, demain)
   en jaune, orange ou rouge ; chaque changement de couleur est ajouté au journal ; une alerte Tchap (facultative) annonce
   les passages au seuil (orange par défaut), avec le nombre d'établissements et d'élèves concernés.
   Téléchargé préréglé depuis l'onglet Veille de l'administration : restent à saisir la clé Météo-France, la clé d'API Grist
   et, si vous voulez l'alerte, le salon Tchap. */

// ===== À RÉGLER =====
const CLE_METEOFRANCE = 'cle-api-meteofrance';                  // portail-api.meteofrance.fr › « Vigilance » › clé d'API (mode « API Key », pas le jeton qui expire en 1 h)
const API_GRIST = 'https://grist.numerique.gouv.fr/o/crise/api';   // serveur et organisation, suivis de /api
const DOC = 'identifiant-du-document';                          // dans l'adresse du document : …/o/crise/<identifiant>/…
const CLE_GRIST = 'cle-api-grist';                              // compte Grist propriétaire du document (Paramètres du compte › Clé d'API)
// Alerte Tchap (facultative : laisser vide pour ne rien envoyer)
const TCHAP_SERVEUR = '';                                       // ex. https://matrix.agent.education.tchap.gouv.fr
const TCHAP_JETON = '';                                         // jeton d'accès du compte qui publie dans le salon
const TCHAP_SALON = '';                                         // identifiant du salon : !abcdef:agent.education.tchap.gouv.fr
const SEUIL_ALERTE = '3';                                       // 3 : orange et rouge ; 4 : rouge seulement
const LIEN_ADMIN = '';                                          // lien de la page d'administration, ajouté à l'alerte
// Préréglé par l'onglet Veille
const TABLE = 'Vigilances';
const JOURNAL = 'Vigilances_journal';
const REFERENTIEL = 'Etablissements';
const COL_DEP = 'Departement';
const COL_EFFECTIF = 'Effectif';
const DEPARTEMENTS = '';                                        // codes suivis, séparés par des virgules ; vide = tous
const DEP_NOMS = {};
// =====================

const URL_MF = 'https://public-api.meteofrance.fr/public/DPVigilance/v1/cartevigilance/encours';
const PHEN = { 1: 'Vent violent', 2: 'Pluie-inondation', 3: 'Orages', 4: 'Crues', 5: 'Neige-verglas', 6: 'Canicule', 7: 'Grand froid', 8: 'Avalanches', 9: 'Vagues-submersion' };
const COUL = ['', 'Vert', 'Jaune', 'Orange', 'Rouge'], PASTILLE = ['', '🟢', '🟡', '🟠', '🔴'];
const COLS = ['Departement_code', 'Departement', 'Phenomene', 'Couleur', 'Niveau', 'Echeance', 'Debut', 'Fin', 'Mise_a_jour', 'Littoral'];
const http = o => this.helpers.httpRequest(o);
const sec = v => v == null || v === '' ? null : typeof v === 'number' ? (v > 1e12 ? v / 1000 : v) : ((Date.parse(v) / 1000) || null);
const nf = n => Math.round(Number(n) || 0).toLocaleString('fr-FR');
const grist = async (chemin, o = {}) => {
  try {
    const r = await http({ url: `${API_GRIST}/docs/${DOC}${chemin}`, method: o.method || 'GET', body: o.body, json: true, timeout: 120000,
      headers: { Authorization: `Bearer ${CLE_GRIST}` } });
    return typeof r === 'string' ? JSON.parse(r) : r;
  } catch (e) { throw new Error(`Grist ${chemin.split('?')[0]} : ${e.message} — vérifiez API_GRIST, DOC et CLE_GRIST`); }
};

// 1. Carte de vigilance en cours
let carte;
try { carte = await http({ url: URL_MF, headers: { apikey: CLE_METEOFRANCE, accept: 'application/json' }, json: true, timeout: 60000 }); }
catch (e) { throw new Error(`Météo-France : ${e.message} — vérifiez CLE_METEOFRANCE (clé d'API de l'API « Vigilance »)`); }
if (typeof carte === 'string') carte = JSON.parse(carte);
const p = (carte && carte.product) || carte || {};
if (!Array.isArray(p.periods) || !p.periods.length) throw new Error('Météo-France : carte de vigilance sans période (format inattendu)');
const maj = sec(p.update_time) || Date.now() / 1000;
const suivis = DEPARTEMENTS.split(',').map(x => x.trim().toUpperCase()).filter(Boolean);
const parCle = new Map();
for (const per of p.periods) {
  const ech = per.echeance === 'J' ? "Aujourd'hui" : per.echeance === 'J1' ? 'Demain' : null;
  if (!ech) continue;
  const debut = sec(per.begin_validity_time), fin = sec(per.end_validity_time);
  for (const d of ((per.timelaps || {}).domain_ids || [])) {
    let code = String(d.domain_id || '').toUpperCase(), littoral = false;
    if (!DEP_NOMS[code] && /^(\d{2}|2A|2B)10$/.test(code)) { code = code.slice(0, -2); littoral = true; }   // littoral d'un département (vagues-submersion)
    if (!DEP_NOMS[code] || (suivis.length && !suivis.includes(code))) continue;
    for (const ph of (d.phenomenon_items || [])) {
      const n = Number(ph.phenomenon_max_color_id);
      if (!(n >= 2 && n <= 4)) continue;
      const phen = PHEN[Number(ph.phenomenon_id)] || `Phénomène ${ph.phenomenon_id}`, k = `${code}|${phen}|${ech}`, prec = parCle.get(k);
      if (prec && prec.Niveau >= n) continue;
      parCle.set(k, { Departement_code: code, Departement: DEP_NOMS[code], Phenomene: phen, Couleur: COUL[n], Niveau: n, Echeance: ech, Debut: debut, Fin: fin, Mise_a_jour: maj, Littoral: littoral });
    }
  }
}
const nouvelles = [...parCle.values()];

// 2. Comparaison avec l'état enregistré
const avant = (await grist(`/tables/${TABLE}/records`)).records || [];
const cle = f => `${f.Departement_code}|${f.Phenomene}|${f.Echeance}`;
const ancien = new Map(avant.map(r => [cle(r.fields || {}), r.fields || {}]));
const changements = [];
for (const f of nouvelles) { const a = ancien.get(cle(f)); if (!a || Number(a.Niveau) !== f.Niveau) changements.push({ f, avant: a ? Number(a.Niveau) || 1 : 1 }); }
for (const [k, a] of ancien) if (!parCle.has(k)) changements.push({ f: { ...a, Niveau: 1, Couleur: 'Vert' }, avant: Number(a.Niveau) || 1 });

// 3. Écriture : table réécrite seulement si quelque chose a changé ; sinon, heure de mise à jour
const actions = [];
if (changements.length) {
  if (avant.length) actions.push(['BulkRemoveRecord', TABLE, avant.map(r => r.id)]);
  if (nouvelles.length) actions.push(['BulkAddRecord', TABLE, nouvelles.map(() => null), Object.fromEntries(COLS.map(c => [c, nouvelles.map(f => f[c])]))]);
  const le = Date.now() / 1000, col = fn => changements.map(fn);
  actions.push(['BulkAddRecord', JOURNAL, changements.map(() => null), { Le: col(() => le), Departement_code: col(c => c.f.Departement_code), Departement: col(c => c.f.Departement),
    Phenomene: col(c => c.f.Phenomene), Echeance: col(c => c.f.Echeance), Avant: col(c => COUL[c.avant] || 'Vert'), Apres: col(c => COUL[c.f.Niveau] || 'Vert'), Niveau: col(c => c.f.Niveau) }]);
} else if (avant.length && avant.some(r => (r.fields || {}).Mise_a_jour !== maj)) {
  actions.push(['BulkUpdateRecord', TABLE, avant.map(r => r.id), { Mise_a_jour: avant.map(() => maj) }]);
}
if (actions.length) await grist('/apply', { method: 'POST', body: actions });

// 4. Alerte Tchap : départements qui atteignent le seuil, avec établissements et élèves concernés
const seuil = Number(SEUIL_ALERTE) || 3;
const montees = changements.filter(c => c.f.Niveau >= seuil && c.avant < seuil);
let alerte = null;
if (montees.length) {
  const norme = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const parNom = new Map(Object.entries(DEP_NOMS).map(([c, n]) => [norme(n), c]));
  const codeDe = v => { const s = String(v || '').trim().toUpperCase(), m = s.match(/^0?(2A|2B|97\d|\d{1,2})\b/); if (m) { const c = m[1].length === 1 ? '0' + m[1] : m[1]; if (DEP_NOMS[c]) return c; } return parNom.get(norme(v)) || null; };
  const parDep = {};
  for (const avecEff of COL_EFFECTIF ? [true, false] : [false]) {
    try {
      const q = `SELECT "${COL_DEP}" AS d, COUNT(*) AS n${avecEff ? `, SUM("${COL_EFFECTIF}") AS e` : ''} FROM "${REFERENTIEL}" GROUP BY "${COL_DEP}"`;
      for (const x of (await grist(`/sql?q=${encodeURIComponent(q)}`)).records || []) {
        const f = x.fields || x, c = codeDe(f.d); if (!c) continue;
        parDep[c] = parDep[c] || { n: 0, e: 0, avecEff }; parDep[c].n += Number(f.n) || 0; parDep[c].e += Number(f.e) || 0;
      }
      break;
    } catch (_) { /* colonne Effectif absente : nouvel essai sans elle */ }
  }
  const groupes = new Map();
  for (const c of montees) { const k = `${c.f.Niveau}|${c.f.Phenomene}|${c.f.Echeance}`; if (!groupes.has(k)) groupes.set(k, []); groupes.get(k).push(c.f); }
  const lignes = [...groupes.entries()].sort((a, b) => b[0].localeCompare(a[0])).map(([k, fs]) => {
    const [n, phen, ech] = k.split('|'), deps = fs.map(f => f.Departement_code);
    const tot = deps.reduce((s, c) => ({ n: s.n + ((parDep[c] || {}).n || 0), e: s.e + ((parDep[c] || {}).e || 0), eff: s.eff || !!(parDep[c] || {}).avecEff }), { n: 0, e: 0, eff: false });
    const chiffres = tot.n ? ` — ${nf(tot.n)} établissement${tot.n > 1 ? 's' : ''}${tot.eff && tot.e ? `, ${nf(tot.e)} élèves` : ''}` : '';
    return { texte: `${PASTILLE[n]} Vigilance ${COUL[n].toLowerCase()} ${phen.toLowerCase()} (${ech.toLowerCase()}) : ${fs.map(f => `${f.Departement} (${f.Departement_code})`).join(', ')}${chiffres}`,
      html: `${PASTILLE[n]} <b>Vigilance ${COUL[n].toLowerCase()} ${phen.toLowerCase()}</b> (${ech.toLowerCase()}) : ${fs.map(f => `${f.Departement} (${f.Departement_code})`).join(', ')}${chiffres}` };
  });
  alerte = { texte: [`PRISME — veille météo`, ...lignes.map(l => l.texte), LIEN_ADMIN ? `Détail : ${LIEN_ADMIN}` : ''].filter(Boolean).join('\n'),
    html: [`<b>PRISME — veille météo</b>`, ...lignes.map(l => l.html), LIEN_ADMIN ? `<a href="${LIEN_ADMIN}">Ouvrir l'onglet Veille</a>` : ''].filter(Boolean).join('<br>') };
  if (TCHAP_SERVEUR && TCHAP_JETON && TCHAP_SALON) {
    try {
      await http({ url: `${TCHAP_SERVEUR.replace(/\/$/, '')}/_matrix/client/v3/rooms/${encodeURIComponent(TCHAP_SALON)}/send/m.room.message/prisme-veille-${Date.now()}`, method: 'PUT', json: true, timeout: 30000,
        headers: { Authorization: `Bearer ${TCHAP_JETON}` }, body: { msgtype: 'm.text', body: alerte.texte, format: 'org.matrix.custom.html', formatted_body: alerte.html } });
      alerte.envoyee = true;
    } catch (e) { alerte.erreur = `Tchap : ${e.message}`; }
  }
}
return [{ json: { mise_a_jour: new Date(maj * 1000).toISOString(), vigilances: nouvelles.length, changements: changements.length, alerte } }];
